7778a|0859c7812ef201f56ed7bdc3a0adf7fc9cfeef82ef9bed9dc080b90a6e1a710e', '[{"source": "model census: teaser-wb-ws-2026-09-27-04-rewrite-v\\rewrite-v-003\\rewrite-v\\ff76a431-09d7-40b4-8dc5-b80211b2e246.answer.json", "url": "output/remediation/model_census/ANSWERS_TRUE_MODEL.jsonl", "quote": "answered_by teaser-wb-ws-2026-09-27-04-rewrite-v-003, answered_at 2026-09-30T00:28:12+00:00, true_model claude-sonnet-5-5"}, {"source": "lane WB run wb-ws-2026-09-27-04, step 11: the final text was written at stage rewrite-v by teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "How the earliest settlement at Barcelona began is unclear, but in about 15 BC the Romans redrew the town as a castrum centred on the Mons Taber, a little hill near the city hall."}, {"source": "scripts/remediation/phase4/model4.py", "url": null, "quote": "the disclosure ''Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09'' names a model that did not write this card; the corrected disclosure is ''Claude Opus and Claude Sonnet (Anthropic): anthropic/claude-opus-5-5 and anthropic/claude-sonnet-5-5 (Claude Code agents), an-sites-remediation-2026-09''"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 85;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _card_disclosure_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'card disclosure correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _card_disclosure_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.new_value IS NULL OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _card_disclosure_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _card_disclosure_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'run', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _card_disclosure_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-disclosure', 'wb-card-disclosure-s002', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'card disclosure correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _card_disclosure_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _card_disclosure_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-card-disclosure-s002'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-card-disclosure-s002'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    -- invariant 3, the lane's own: no planned site is one of the
    -- planned sites whose card provenance names neither disclosure
    SELECT count(*) INTO bad FROM unified_sites
     WHERE id IN (SELECT site_id FROM _card_disclosure_plan)
       AND (coalesce(raw_data -> '_card_provenance' ->> 'ai_system', '') NOT IN ('Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09', 'Claude Opus and Claude Sonnet (Anthropic): anthropic/claude-opus-5-5 and anthropic/claude-sonnet-5-5 (Claude Code agents), an-sites-remediation-2026-09'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'card disclosure correction: % planned site(s) break the lane invariant after the write', bad;
    END IF;

    RAISE NOTICE 'card disclosure correction: % of % planned cell(s) changed and journalled over 85 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-card-disclosure-s002'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/card-disclosure'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-card-disclosure-s002' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('raw_data')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'raw_data' THEN u.raw_data IS NOT DISTINCT FROM l.new_value::jsonb
                ELSE false END)
UNION ALL
SELECT 'listed sites of this step still naming the Opus-only disclosure', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND id IN ('8d4f7a98-2c79-4a0e-ae9b-c8f4a665902f', '8d96a44c-dbe5-4d08-875f-fd67534ae9cb', '8fe59448-2356-47b1-810a-d31c76a580e3', '9072416f-69c6-4c4a-a5d3-6981eb899114', '918025af-8cfa-47db-a273-b4b715590e0c', '93dd77da-64ad-4947-96b3-8ead4d6c98c1', '9b34941b-70ae-4be4-80a5-eefc3c470ce0', '9c2327c0-112b-4d32-9d73-c4ffac345288', '9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a', '9dbff73b-6505-430a-9b75-8630df8b451c', 'a1118dbb-9f77-4aae-a1d9-7fd43a7b29ec', 'a1174754-0d0f-4d54-8802-e51658125770', 'a28e4962-5513-4955-b1e0-d6a8f8f244cc', 'a45b9287-fe45-43b0-a8d6-8c434e16e65b', 'a52e274f-3e08-44b5-a03f-1d564fede9a2', 'a6d5b07a-c9ea-4e5a-a82d-4416a045f1bc', 'a7abbf5d-8bea-4e7f-9df8-bb82169889ab', 'a98dcb51-39c4-4ab9-b34e-1f10a9aa14d9', 'aa60e5f1-a3f5-4f27-b152-44ad38e72f54', 'abe8f81a-dcdb-42b8-9f99-a763c858fd7f', 'ad16f637-fa0c-4920-bfae-7a53dee2593a', 'b065a36f-0e01-4de3-9100-409a15eeb532', 'b07c4d65-158e-4e9d-9817-f39161b7516d', 'b0c061fd-8644-433e-a61c-9b20fd960c26', 'b1410fda-e006-411f-a8ce-64513976d158', 'b1b150e6-ebca-4c21-ad56-ddccd8c9afcc', 'b269e1ad-573d-4cd1-8bb2-581a74b5f565', 'b2943cf3-26cd-437e-bdc6-0232105b38b6', 'b306aff1-60d0-4d34-85e3-fe206911dc65', 'b97f1e4c-09df-4190-aed5-22bfeb4a45cc', 'ba0ce1ee-9848-4de1-9884-0e0bb37e2abd', 'ba33abc5-f266-4b9c-85f1-cd691699b271', 'baf13030-1578-4edc-a351-ca627828a326', 'bf6f967e-3161-45c3-840d-d68ebff231b7', 'c0526e60-577b-4f28-9a07-e3c5739984bd', 'c0dce315-a1ed-4be6-8dd2-df515e754875', 'c345810f-7f8d-4845-88c7-64c652fa34d1', 'c3517388-2457-42fd-9cf8-f6a043021b1e', 'c4bfc499-08d9-4cd2-ac3f-91ddaa743710', 'c889f267-d523-4253-8bc4-ec3eec0244c2', 'c9066b1a-0da8-436f-ad87-cdec31e99366', 'c97527d0-4640-4b04-9bd6-132fcb6fd17d', 'cb672d70-399c-4bf5-8032-3259832f53eb', 'cca3b72c-8ad4-481b-838f-64bc69cf11a0', 'ccb5fcce-35d3-463a-bb98-0cfc09918465', 'cd8a601a-db65-43d3-82a5-afd0d7cf3e8f', 'ce8a19e4-c1b3-42e6-9bf9-4eb5600c0650', 'cff3c769-e793-40f3-897c-4b085cdf9b56', 'd0dab028-351d-48e1-b749-821e89458